_acme_complete() {
  local cur="${COMP_WORDS[COMP_CWORD]}" path="" i w
  for ((i = 1; i < COMP_CWORD; i++)); do
    w="${COMP_WORDS[i]}"
    case " $(_acme_subs "$path") " in *" $w "*) path="${path:+$path }$w" ;; esac
  done
  COMPREPLY=($(compgen -W "$(_acme_subs "$path") $(_acme_opts "$path")" -- "$cur"))
}
complete -F _acme_complete acme

